    },
    {
      "indicator": "MM50",
      "reading": "58.7268",
      "interpretation": "Suporte de médio prazo; ainda acima da MM200, sustentando viés comprador."
    },
    {
      "indicator": "MM200",
      "reading": "55.4764",
      "interpretation": "Tendência de longo prazo positiva; nível de suporte estrutural relevante."
    },
    {
